 tb=("A friend says 10 lakh and 1 million are different numbers. How will you explain?",["Ten lakh is 10,00,000 and one million is 1,000,000. They are the same number.","The names differ between the two systems."],["Thinking different names mean different values."]),
 summary=["Indian system: commas after 3 digits, then every 2 digits.","1 lakh = 100,000; 10 lakh = 1 million; 1 crore = 10 million.","More digits means a bigger number."],
